import{_ as t,o as a,c as r,a2 as l}from"./chunks/framework.DfDAiEgj.js";const h=JSON.parse('{"title":"知识产权","description":"","frontmatter":{},"headers":[],"relativePath":"data-dive/intellectual property.md","filePath":"data-dive/intellectual property.md","lastUpdated":null}'),i={name:"data-dive/intellectual property.md"};function p(o,e,n,s,c,_){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="知识产权" tabindex="-1">知识产权 <a class="header-anchor" href="#知识产权" aria-label="Permalink to &quot;知识产权&quot;">​</a></h1><p>《中国人工智能产业知识产权白皮书2020》已于2021年2月3日正式发布：</p><p><a href="http://www.iprdaily.cn/article_27004.html" target="_blank" rel="noreferrer">http://www.iprdaily.cn/article_27004.html</a></p><p>专利技术：<a href="http://xjishu.com/" target="_blank" rel="noreferrer">http://xjishu.com/</a></p><p>他不创新让你去创新，你死了他一眼都不会看你的，你活了那你的创新就是他的了<a href="https://www.bilibili.com/video/BV1Y64y1o7ys?spm_id_from=333.851.b_7265636f6d6d656e64.3" target="_blank" rel="noreferrer">1</a></p><p>软件著作权申请流程详细介绍（从注册到受理）：<a href="https://space.bilibili.com/327555880?from=search&amp;seid=6875613928804232436" target="_blank" rel="noreferrer">https://space.bilibili.com/327555880?from=search&amp;seid=6875613928804232436</a></p><p>第十条 著作权包括下列人身权和财产权： （一）发表权，即决定作品是否公之于众的权利； （二）署名权，即表明作者身份，在作品上署名的权利； （三）修改权，即修改或者授权他人修改作品的权利； （四）保护作品完整权，即保护作品不受歪曲、篡改的权利； （五）复制权，即以印刷、复印、拓印、录音、录像、翻录、翻拍等方式将作品制作一份或者多份的权利； （六）发行权，即以出售或者赠与方式向公众提供作品的原件或者复制件的权利； （七）出租权，即有偿许可他人临时使用电影作品和以类似摄制电影的方法创作的作品、计算机软件的权利，计算机软件不是出租的主要标的的除外； （八）展览权，即公开陈列美术作品、摄影作品的原件或者复制件的权利； （九）表演权，即公开表演作品，以及用各种手段公开播送作品的表演的权利； （十）放映权，即通过放映机、幻灯机等技术设备公开再现美术、摄影、电影和以类似摄制电影的方法创作的作品等的权利； （十一）广播权，即以无线方式公开广播或者传播作品，以有线传播或者转播的方式向公众传播广播的作品，以及通过扩音器或者其他传送符号、声音、图像的类似工具向公众传播广播的作品的权利； （十二）信息网络传播权，即以有线或者无线方式向公众提供作品，使公众可以在其个人选定的时间和地点获得作品的权利； （十三）摄制权，即以摄制电影或者以类似摄制电影的方法将作品固定在载体上的权利； （十四）改编权，即改变作品，创作出具有独创性的新作品的权利； （十五）翻译权，即将作品从一种语言文字转换成另一种语言文字的权利； （十六）汇编权，即将作品或者作品的片段通过选择或者编排，汇集成新作品的权利； （十七）应当由著作权人享有的其他权利。 著作权人可以许可他人行使前款第（五）项至第（十七）项规定的权利，并依照约定或者本法有关规定获得报酬。 著作权人可以全部或者部分转让本条第一款第（五）项至第（十七）项规定的权利，并依照约定或者本法有关规定获得报酬。</p>',7)])])}const m=t(i,[["render",p]]);export{h as __pageData,m as default};
